(() => {
  const stealthAdBypass = () => {
    try {
      // 1) Remove actual ad containers (so video ads never render)
      document.querySelectorAll('.ytd-display-ad-renderer').forEach(el => el.remove());
      document.querySelectorAll('ytd-player-legacy-desktop-watch-ads-renderer').forEach(el => el.remove());

      // 2) Hide just the thumbnail 'AD' badge overlays (don’t remove parent)
      document.querySelectorAll('ytd-thumbnail-overlay-side-panel-renderer[overlay-style="AD"]').forEach(el => {
        el.style.display = 'none';
      });

      // 3) Override ytInitialPlayerResponse before YouTube reads it
      Object.defineProperty(window, 'ytInitialPlayerResponse', {
        configurable: true,
        get: () => {
          const real = window.__ytRealResp || {};
          if (real.adPlacements) delete real.adPlacements;
          if (real.playerAds) delete real.playerAds;
          return real;
        },
        set: (val) => {
          if (val && val.adPlacements) delete val.adPlacements;
          if (val && val.playerAds) delete val.playerAds;
          window.__ytRealResp = val;
        }
      });

      // 4) Patch any "isAd" flags so they always report false
      const originalDefine = Object.defineProperty;
      Object.defineProperty = function(obj, prop, desc) {
        if (prop === 'isAd') desc.value = false;
        return originalDefine.call(Object, obj, prop, desc);
      };
    } catch (e) { console.warn('stealthAdBypass error', e); }
  };

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', stealthAdBypass);
  } else {
    stealthAdBypass();
  }
})();
